import{f as t}from"./index-C_A-ZndS.js";const o={listar(e=!0){return t.get("/incidentes",{params:{incluir_fechados:e}})},painel(){return t.get("/incidentes/painel")},obter(e){return t.get(`/incidentes/${e}`)},criar(e){return t.post("/incidentes",e)},atualizar(e,i){return t.patch(`/incidentes/${e}`,i)},alterarEstado(e,i,n=""){return t.post(`/incidentes/${e}/estado`,{estado:i,nota:n})},taxonomia(){return t.get("/incidentes/taxonomia")},documento(e,i){return t.get(`/incidentes/${e}/documento/${i}`)},registarNotificacao(e,i){return t.post(`/incidentes/${e}/notificacoes`,i)},listarNotificacoes(e){return t.get(`/incidentes/${e}/notificacoes`)},obterNotificacao(e,i){return t.get(`/incidentes/${e}/notificacoes/${i}`)},adicionarEvento(e,i){return t.post(`/incidentes/${e}/eventos`,i)},relatorio(e){return t.get(`/incidentes/${e}/relatorio`)},eliminar(e){return t.delete(`/incidentes/${e}`)}};export{o as i};
